INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4704766, 677401, 10686, '<td valign="top">Great subject, but I think the flag in the BG takes away from the bike.</td>', 'Great subject, but I think the flag in the BG takes away from the bike.', '2008-05-15 16:41:08.000000', NULL, 1),
(4704784, 678596, 10686, '<td valign="top">I think you really missed showing the beauty of Montana de Oro with a bike and instead got an unflattering picture of this girl''s rump.</td>', 'I think you really missed showing the beauty of Montana de Oro with a bike and instead got an unflattering picture of this girl''s rump.', '2008-05-15 16:48:07.000000', NULL, 1),
(4704788, 677201, 10686, '<td valign="top">I like this because it leaves the viewer with a question and no clue as to the answer.</td>', 'I like this because it leaves the viewer with a question and no clue as to the answer.', '2008-05-15 16:49:25.000000', NULL, 1),
(4704792, 678598, 10686, '<td valign="top">The spatial relationship between the high and low tones is just a bit off, but not by much and not enough to interrupt their interplay. Well done.</td>', 'The spatial relationship between the high and low tones is just a bit off, but not by much and not enough to interrupt their interplay. Well done.', '2008-05-15 16:51:19.000000', NULL, 1),
(4704798, 678569, 10686, '<td valign="top">What''s the point?</td>', 'What''s the point?', '2008-05-15 16:53:52.000000', NULL, 1),
(4704864, 677516, 77192, '<td valign="top">I''m a bit puzzled as to why he has an audience, is this some event or another?<br/> <br/>He''s nicely lit and isolated from the background. Good work.</td>', 'I''m a bit puzzled as to why he has an audience, is this some event or another? He''s nicely lit and isolated from the background. Good work.', '2008-05-15 17:23:33.000000', NULL, 1),
