(4708100, 677597, 47852, '<td valign="top">Interesting interpretation of the challenge (and refreshing after seeing so many wheels and chains).  Wish the technicals were a little stronger so I could give it a higher score, but it gets points for originality!</td>', 'Interesting interpretation of the challenge (and refreshing after seeing so many wheels and chains).  Wish the technicals were a little stronger so I could give it a higher score, but it gets points for originality!', '2008-05-17 08:59:01.000000', NULL, 1),
(4708103, 678607, 47852, '<td valign="top">I like the warmer colors in this one and the shallow dof is great.  The shot as a whole feels a bit too static for me.  Perhaps using a diagonal, with just the chain leading from corner to corner, or even tilting the entire shot would have been a bit more interesting?  Nicely done though!</td>', 'I like the warmer colors in this one and the shallow dof is great.  The shot as a whole feels a bit too static for me.  Perhaps using a diagonal, with just the chain leading from corner to corner, or even tilting the entire shot would have been a bit more interesting?  Nicely done though!', '2008-05-17 09:03:41.000000', NULL, 1),
(4708105, 677831, 47852, '<td valign="top">Love the use of just the shadow, and the negative space here.  Great job.</td>', 'Love the use of just the shadow, and the negative space here.  Great job.', '2008-05-17 09:04:11.000000', NULL, 1),
(4708110, 678485, 47852, '<td valign="top">I think the thing that bothers me about this is the front wheel shape not being complete.  But you seem to have gotten the bike sitting pretty straight to make for a nice silhouette... and I don''t see the kickstand down?</td>', 'I think the thing that bothers me about this is the front wheel shape not being complete.  But you seem to have gotten the bike sitting pretty straight to make for a nice silhouette... and I don''t see the kickstand down?', '2008-05-17 09:08:23.000000', NULL, 1),
(4708112, 678080, 47852, '<td valign="top">Points for originality in the challenge.. your model seems to get a bit lost in the clouds.  I wish he had been placed in a bit clearer area, though you did a nice job lining the bicycle up in a clear spot to make it stand out.</td>', 'Points for originality in the challenge.. your model seems to get a bit lost in the clouds.  I wish he had been placed in a bit clearer area, though you did a nice job lining the bicycle up in a clear spot to make it stand out.', '2008-05-17 09:10:00.000000', NULL, 1),
(4708116, 677156, 47852, '<td valign="top">Unique, simple, interesting lines and shapes, and well composed in the frame.  One of my top picks for the challenge (even though I have no idea why the bike seems to be on a pole).  The only thing that bugs me is those little white spots.</td>', 'Unique, simple, interesting lines and shapes, and well composed in the frame.  One of my top picks for the challenge (even though I have no idea why the bike seems to be on a pole).  The only thing that bugs me is those little white spots.', '2008-05-17 09:12:11.000000', NULL, 1),
(4708117, 678514, 47852, '<td valign="top">Great composition and lighting (and I like the color too).  The soft sense of the spinning wheels is great.  Well done.</td>', 'Great composition and lighting (and I like the color too).  The soft sense of the spinning wheels is great.  Well done.', '2008-05-17 09:13:00.000000', NULL, 1),
(4708119, 678446, 47852, '<td valign="top">Thought there would be many more shots like this, but for me this one rises to the top of the pack.  Like the complimentary colors here, and you handled the panning very nicely.  The space you left at the top gives a nice balance.  Great job!</td>', 'Thought there would be many more shots like this, but for me this one rises to the top of the pack.  Like the complimentary colors here, and you handled the panning very nicely.  The space you left at the top gives a nice balance.  Great job!', '2008-05-17 09:14:26.000000', NULL, 1),
(4708120, 677428, 47852, '<td valign="top">Love the use of the shadow here, and the line is a nice way to help lead the eye through the photo.  Fantastic job!</td>', 'Love the use of the shadow here, and the line is a nice way to help lead the eye through the photo.  Fantastic job!', '2008-05-17 09:15:04.000000', NULL, 1),
(4708260, 678589, 14867, '<td valign="top">Very good effect, would be almost perefct if the biker was on left side</td>', 'Very good effect, would be almost perefct if the biker was on left side', '2008-05-17 11:46:31.000000', NULL, 1),
(4708263, 678577, 14867, '<td valign="top">Unusual POV and composition, interesting but a bit confused IMO. The orange biker is distracting.</td>', 'Unusual POV and composition, interesting but a bit confused IMO. The orange biker is distracting.', '2008-05-17 11:51:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
