(4708271, 677912, 89230, '<td valign="top">I see the title, but Im not a fan of the effects</td>', 'I see the title, but Im not a fan of the effects', '2008-05-17 11:55:18.000000', NULL, 1),
(4708272, 678598, 89230, '<td valign="top">I think a better crop wouldve helped out this shot</td>', 'I think a better crop wouldve helped out this shot', '2008-05-17 11:55:51.000000', NULL, 1),
(4708273, 678358, 14867, '<td valign="top">Good idea and good composition, unfortunately there is <i>nothing</i> sharp- not even the frame''s crossbars.</td>', 'Good idea and good composition, unfortunately there is nothing sharp- not even the frame''s crossbars.', '2008-05-17 11:56:07.000000', NULL, 1),
(4708275, 677507, 14867, '<td valign="top">Original and beautiful, just great!</td>', 'Original and beautiful, just great!', '2008-05-17 11:56:57.000000', NULL, 1),
(4708278, 678513, 89230, '<td valign="top">Oversaturated and not very well composed</td>', 'Oversaturated and not very well composed', '2008-05-17 11:57:54.000000', NULL, 1),
(4708279, 678643, 14867, '<td valign="top">Rather good and creative in this subcategory abstract details from the bicycle. Light a bit harsh IMO.</td>', 'Rather good and creative in this subcategory abstract details from the bicycle. Light a bit harsh IMO.', '2008-05-17 11:59:17.000000', NULL, 1),
(4708281, 678514, 89230, '<td valign="top">Maybe sharpening this would make the spokes stand out a bit more</td>', 'Maybe sharpening this would make the spokes stand out a bit more', '2008-05-17 12:00:36.000000', NULL, 1),
(4708283, 677516, 89230, '<td valign="top">You should crop this on the right a bit, so that he is riding into the picture instead of being centered. It would look better.</td>', 'You should crop this on the right a bit, so that he is riding into the picture instead of being centered. It would look better.', '2008-05-17 12:02:00.000000', NULL, 1),
(4708284, 677666, 14867, '<td valign="top">Excellent technique</td>', 'Excellent technique', '2008-05-17 12:02:53.000000', NULL, 1),
(4708287, 678543, 89230, '<td valign="top">I think a tighter crop, left and right, would make it be better. You can already see the flowers in the background and forefront. If the bike it the POI then it should take up more of the picture. And traditionally, this has weird dimensions so I dont think it will rate as well</td>', 'I think a tighter crop, left and right, would make it be better. You can already see the flowers in the background and forefront. If the bike it the POI then it should take up more of the picture. And traditionally, this has weird dimensions so I dont think it will rate as well', '2008-05-17 12:05:06.000000', NULL, 1),
(4708289, 678533, 89230, '<td valign="top">Great shot. Only recommendation is to sharpen it up a bit more. But that could be because of the kb limit.<br/> <br/>Either way, best in the challenge.</td>', 'Great shot. Only recommendation is to sharpen it up a bit more. But that could be because of the kb limit. Either way, best in the challenge.', '2008-05-17 12:06:15.000000', NULL, 1),
(4708295, 677735, 89230, '<td valign="top">Nice colors. Image is a bit small though. Would probably rank higher if the photo was bigger</td>', 'Nice colors. Image is a bit small though. Would probably rank higher if the photo was bigger', '2008-05-17 12:08:22.000000', NULL, 1),
(4708297, 678044, 92383, '<td valign="top">Did the same thing, but didn''t submit - I like yours.</td>', 'Did the same thing, but didn''t submit - I like yours.', '2008-05-17 12:09:56.000000', NULL, 1),
(4708300, 678463, 92383, '<td valign="top">This reminds me of a whiterook photo "where are all the boats" or something like that.  Helpful I know :)</td>', 'This reminds me of a whiterook photo "where are all the boats" or something like that.  Helpful I know :)', '2008-05-17 12:10:44.000000', NULL, 1),
(4708301, 677656, 27421, '<td valign="top">Like the frame...what did you use to create it?</td>', 'Like the frame...what did you use to create it?', '2008-05-17 12:10:48.000000', NULL, 1),
(4708305, 678341, 92383, '<td valign="top">I love the pic.  Some super patriot types will be offended the flag is backward perhaps.  Whatever for me, but for some little edge perhaps a horizontal flip would have tweaked a little.  9 for me... great bike.</td>', 'I love the pic.  Some super patriot types will be offended the flag is backward perhaps.  Whatever for me, but for some little edge perhaps a horizontal flip would have tweaked a little.  9 for me... great bike.', '2008-05-17 12:12:29.000000', NULL, 1),
(4708317, 677921, 88590, '<td valign="top">I love your colours, your sharpness, the lighting - it''s all excellent.  My only issue is that I imagine the bike is on the side of the building, and given your composition / perspective, this doesn''t appear to be this way at all.  Maybe a different angle...?</td>', 'I love your colours, your sharpness, the lighting - it''s all excellent.  My only issue is that I imagine the bike is on the side of the building, and given your composition / perspective, this doesn''t appear to be this way at all.  Maybe a different angle...?', '2008-05-17 12:18:44.000000', NULL, 1),
(4708323, 677428, 14867, '<td valign="top">Very, very good. Great sense of the moment (biker lit in the shadow) and of the composition. Congrats</td>', 'Very, very good. Great sense of the moment (biker lit in the shadow) and of the composition. Congrats', '2008-05-17 12:27:18.000000', NULL, 1),
(4708324, 678614, 14867, '<td valign="top">Different, interesting, elegant. Superb use of DOF.</td>', 'Different, interesting, elegant. Superb use of DOF.', '2008-05-17 12:28:08.000000', NULL, 1),
