(4708380, 677507, 87751, '<td valign="top">Great shot.  Very clever indeed.</td>', 'Great shot.  Very clever indeed.', '2008-05-17 13:59:40.000000', NULL, 1),
(4708381, 678319, 87751, '<td valign="top">Beautiful light --- and a nice composition too.</td>', 'Beautiful light --- and a nice composition too.', '2008-05-17 13:59:46.000000', NULL, 1),
