(4708414, 678643, 92639, '<td valign="top">I like how you used the diagonal - very interesting.</td>', 'I like how you used the diagonal - very interesting.', '2008-05-17 15:56:22.000000', NULL, 1),
(4708441, 678227, 76598, '<td valign="top">good possibilities here, I would have preferred more depth of field and knocking down the glare on the bell</td>', 'good possibilities here, I would have preferred more depth of field and knocking down the glare on the bell', '2008-05-17 16:58:16.000000', NULL, 1),
(4708452, 678519, 76598, '<td valign="top">I am really conflicted by this image.  I like the simplicity and the potential message, but somehow at the same time it isn''t grabbing me.  The technical quality is good.  My gut tells me it just needs a little something more.  Some thoughts are perhaps a catchy title, a darker sky, parts laying around.  To really love the image, I need just a tad more.</td>', 'I am really conflicted by this image.  I like the simplicity and the potential message, but somehow at the same time it isn''t grabbing me.  The technical quality is good.  My gut tells me it just needs a little something more.  Some thoughts are perhaps a catchy title, a darker sky, parts laying around.  To really love the image, I need just a tad more.', '2008-05-17 17:08:16.000000', NULL, 1),
(4708476, 678026, 88136, '<td valign="top">great color</td>', 'great color', '2008-05-17 17:27:53.000000', NULL, 1),
(4708477, 678445, 88136, '<td valign="top">lol nice gloves:)</td>', 'lol nice gloves:)', '2008-05-17 17:28:07.000000', NULL, 1),
(4708479, 677156, 88136, '<td valign="top">cool idea, the white line is kinda distracting where it cuts the handle part of the bike, but other than that i like this photo alot:)</td>', 'cool idea, the white line is kinda distracting where it cuts the handle part of the bike, but other than that i like this photo alot:)', '2008-05-17 17:28:45.000000', NULL, 1),
(4708487, 678519, 19799, '<td valign="top">Looks a little under exposed but it''s still a very nice photo.</td>', 'Looks a little under exposed but it''s still a very nice photo.', '2008-05-17 17:47:14.000000', NULL, 1),
(4708489, 678434, 19799, '<td valign="top">Too many distracting elements even the frame of the bike stands out.</td>', 'Too many distracting elements even the frame of the bike stands out.', '2008-05-17 17:47:55.000000', NULL, 1),
(4708491, 678577, 19799, '<td valign="top">Not sure the foreground bike lends anything positive to the photo. Maybe if more of the bike was showing.</td>', 'Not sure the foreground bike lends anything positive to the photo. Maybe if more of the bike was showing.', '2008-05-17 17:48:32.000000', NULL, 1),
(4708494, 678446, 19799, '<td valign="top">Very nice panning shot. Colours of the rider and dark background is nice touch too.</td>', 'Very nice panning shot. Colours of the rider and dark background is nice touch too.', '2008-05-17 17:49:16.000000', NULL, 1),
(4708495, 678556, 19799, '<td valign="top">This photo definitely is telling a story! It seems a bit over exposed but the colours work very nice together.</td>', 'This photo definitely is telling a story! It seems a bit over exposed but the colours work very nice together.', '2008-05-17 17:50:07.000000', NULL, 1),
(4708497, 677867, 19799, '<td valign="top">The lack of focus hurts this photo. The colour of the bike is a very good element to have for this shot though.</td>', 'The lack of focus hurts this photo. The colour of the bike is a very good element to have for this shot though.', '2008-05-17 17:51:02.000000', NULL, 1),
(4708498, 678627, 19799, '<td valign="top">I think more of the bike showing would help this shot.</td>', 'I think more of the bike showing would help this shot.', '2008-05-17 17:51:42.000000', NULL, 1),
(4708500, 677346, 19799, '<td valign="top">Cool looking capture.</td>', 'Cool looking capture.', '2008-05-17 17:52:07.000000', NULL, 1),
(4708502, 678499, 19799, '<td valign="top">Great idea. I also like how you have the hub of the wheel off-center in the photo.</td>', 'Great idea. I also like how you have the hub of the wheel off-center in the photo.', '2008-05-17 17:52:51.000000', NULL, 1),
(4708503, 678491, 19799, '<td valign="top">The harsh flash in the upper right distracts from the shot.</td>', 'The harsh flash in the upper right distracts from the shot.', '2008-05-17 17:53:19.000000', NULL, 1),
(4708505, 678287, 19799, '<td valign="top">Not sure about the diagonal composition but the colour saturation is very nice.</td>', 'Not sure about the diagonal composition but the colour saturation is very nice.', '2008-05-17 17:53:48.000000', NULL, 1),
(4708506, 677714, 19799, '<td valign="top">Not really seeing the bike theme in this shot. Good capture though.</td>', 'Not really seeing the bike theme in this shot. Good capture though.', '2008-05-17 17:54:17.000000', NULL, 1),
(4708508, 678111, 19799, '<td valign="top">Many distracting elements and the harsh lighting is a distraction.</td>', 'Many distracting elements and the harsh lighting is a distraction.', '2008-05-17 17:54:48.000000', NULL, 1),
