(4709610, 678520, 92817, '<td valign="top">Very nice photo.  I love how the clouds pull even more attention to the bicycle.  The silhouette of the bike is the obvious focus here even though it isnt centered in the frame, very nice.</td>', 'Very nice photo.  I love how the clouds pull even more attention to the bicycle.  The silhouette of the bike is the obvious focus here even though it isnt centered in the frame, very nice.', '2008-05-18 13:30:52.000000', NULL, 1),
(4709620, 677449, 92817, '<td valign="top">Ive seen a few similar photographs in the competition, but you framed this shot very nicely! well done.  Its very interesting to just look at.</td>', 'Ive seen a few similar photographs in the competition, but you framed this shot very nicely! well done.  Its very interesting to just look at.', '2008-05-18 13:38:34.000000', NULL, 1),
(4709765, 677825, 90777, '<td valign="top">I think black and white, or sepia may have given an even stronger feel that the bike is going nowhere and has been left to rot.  Also a little too much Ivy in the bottom of the frame, maybe you could take a step forward and fill the frame with the bike with just a hint of Ivy creeping over the bike</td>', 'I think black and white, or sepia may have given an even stronger feel that the bike is going nowhere and has been left to rot.  Also a little too much Ivy in the bottom of the frame, maybe you could take a step forward and fill the frame with the bike with just a hint of Ivy creeping over the bike', '2008-05-18 16:33:04.000000', NULL, 1),
(4709766, 678027, 90777, '<td valign="top">A good combination of image and title.  Fits the challenge very well</td>', 'A good combination of image and title.  Fits the challenge very well', '2008-05-18 16:34:05.000000', NULL, 1),
(4709773, 678524, 90777, '<td valign="top">I feel as if not much effort went in to obtaining this image, like it was a grab shot in the street.  I''d prefer to have seen it from the front of the riders and without the cars in the BG</td>', 'I feel as if not much effort went in to obtaining this image, like it was a grab shot in the street.  I''d prefer to have seen it from the front of the riders and without the cars in the BG', '2008-05-18 16:37:45.000000', NULL, 1),
(4709775, 677011, 90777, '<td valign="top">Great image, I suspect it will place higher than my effort on the same theme.</td>', 'Great image, I suspect it will place higher than my effort on the same theme.', '2008-05-18 16:38:31.000000', NULL, 1),
