INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4710685, 678575, 69368, '<td valign="top">interesting crop and good sharpness. Only the background distracts a tad to me: looks like a blanket or sheet..</td>', 'interesting crop and good sharpness. Only the background distracts a tad to me: looks like a blanket or sheet..', '2008-05-19 04:04:27.000000', NULL, 1),
(4710686, 678080, 69368, '<td valign="top">very funny and creative idea!</td>', 'very funny and creative idea!', '2008-05-19 04:05:23.000000', NULL, 1),
(4710687, 677057, 69368, '<td valign="top">beautiful composition</td>', 'beautiful composition', '2008-05-19 04:06:08.000000', NULL, 1),
(4710691, 678617, 69368, '<td valign="top">interesting perspective. too bad his face is out of focus</td>', 'interesting perspective. too bad his face is out of focus', '2008-05-19 04:08:13.000000', NULL, 1),
(4710699, 678353, 69368, '<td valign="top">this is one of my favorite shots in the challenge! The tones are just right, crop is perfect, love the unsharpness of the bike. the couple in background is really nice. Very good seen! And a lovely little story</td>', 'this is one of my favorite shots in the challenge! The tones are just right, crop is perfect, love the unsharpness of the bike. the couple in background is really nice. Very good seen! And a lovely little story', '2008-05-19 04:11:50.000000', NULL, 1),
(4710743, 677796, 26559, '<td valign="top">There is so much going on in the frame here...my preference would be to choose a different composition to really make it clear what is the subject of your image and what is important about it.</td>', 'There is so much going on in the frame here...my preference would be to choose a different composition to really make it clear what is the subject of your image and what is important about it.', '2008-05-19 04:56:28.000000', NULL, 1),
(4710745, 677507, 26559, '<td valign="top">Interesting idea, I like how you combined the three cyclist images.  The light is very harsh, though you would have to think carefully about your lighting to keep the shadow as it is.</td>', 'Interesting idea, I like how you combined the three cyclist images.  The light is very harsh, though you would have to think carefully about your lighting to keep the shadow as it is.', '2008-05-19 04:59:53.000000', NULL, 1),
(4710746, 678111, 26559, '<td valign="top">Seems very cluttered, subject is not clearly defined to me.</td>', 'Seems very cluttered, subject is not clearly defined to me.', '2008-05-19 05:00:33.000000', NULL, 1),
(4710750, 677888, 26559, '<td valign="top">More interesting than many shots in this challenge.  I would have liked to see a tighter crop behind and above the cyclist, and more room in front for him to "ride into", but that''s just my preference.  Nice panning shot.</td>', 'More interesting than many shots in this challenge.  I would have liked to see a tighter crop behind and above the cyclist, and more room in front for him to "ride into", but that''s just my preference.  Nice panning shot.', '2008-05-19 05:06:15.000000', NULL, 1),
(4710755, 678446, 26559, '<td valign="top">Would rather see this in landscape format...top of image does not contribute very much.  Nice pan, though.</td>', 'Would rather see this in landscape format...top of image does not contribute very much.  Nice pan, though.', '2008-05-19 05:10:11.000000', NULL, 1),
(4710783, 678434, 89424, '<td valign="top">The lighting in this picture is very dark. and the green leaves in the foreground are distracting.</td>', 'The lighting in this picture is very dark. and the green leaves in the foreground are distracting.', '2008-05-19 05:45:57.000000', NULL, 1),
(4710822, 677671, 89424, '<td valign="top">This picture has a good use of panning but i believe that it is not balanced.</td>', 'This picture has a good use of panning but i believe that it is not balanced.', '2008-05-19 06:18:12.000000', NULL, 1),
(4710825, 678556, 89424, '<td valign="top">This photograph ha a sense of unity because of it''s analogous color scheme.</td>', 'This photograph ha a sense of unity because of it''s analogous color scheme.', '2008-05-19 06:19:39.000000', NULL, 1),
(4710827, 678484, 89424, '<td valign="top">This photograph is trong because most of the color is in the center of the picture in the window and that color contrasted with the outside.</td>', 'This photograph is trong because most of the color is in the center of the picture in the window and that color contrasted with the outside.', '2008-05-19 06:20:41.000000', NULL, 1),
(4710830, 677831, 89424, '<td valign="top">This photograph is strong because of the use of the border unifying with the composition, but there seems to be a large amount of negative space.</td>', 'This photograph is strong because of the use of the border unifying with the composition, but there seems to be a large amount of negative space.', '2008-05-19 06:22:24.000000', NULL, 1),
(4710832, 678650, 89424, '<td valign="top">This photograph is original because it displays a reverse panning, there is not one focus point of the photograph.</td>', 'This photograph is original because it displays a reverse panning, there is not one focus point of the photograph.', '2008-05-19 06:24:31.000000', NULL, 1),
(4710834, 678401, 89424, '<td valign="top">The lines on the large metal part lead the viewers eyes back to spokes in the foreground, but those are out of focus so it detracts from the photograph,</td>', 'The lines on the large metal part lead the viewers eyes back to spokes in the foreground, but those are out of focus so it detracts from the photograph,', '2008-05-19 06:26:05.000000', NULL, 1),
(4710852, 678027, 89424, '<td valign="top">There is almost an imbalance of positive and negative space. This photograph would stand out more if the white strings on the handles were brighter and contrasted more with the background.</td>', 'There is almost an imbalance of positive and negative space. This photograph would stand out more if the white strings on the handles were brighter and contrasted more with the background.', '2008-05-19 06:58:49.000000', NULL, 1),
(4710853, 678577, 89424, '<td valign="top">This photograph is trong because it has a strong sense of fore-, middle- and background.</td>', 'This photograph is trong because it has a strong sense of fore-, middle- and background.', '2008-05-19 06:59:55.000000', NULL, 1),
(4710854, 677234, 89424, '<td valign="top">This spokes in this picture are very in focus. They makes a very interesting pattern through out the picture. The photograph also has a nice range of values.</td>', 'This spokes in this picture are very in focus. They makes a very interesting pattern through out the picture. The photograph also has a nice range of values.', '2008-05-19 07:00:24.000000', NULL, 1),
(4710857, 677624, 89424, '<td valign="top">The line of the handle bar leads the eye across the photograph and it bisects the picture. The handle bar is also horizontal so there is a stronger sense of balance.</td>', 'The line of the handle bar leads the eye across the photograph and it bisects the picture. The handle bar is also horizontal so there is a stronger sense of balance.', '2008-05-19 07:02:09.000000', NULL, 1),
(4710858, 678575, 89424, '<td valign="top">This photograph has a rich range of values.</td>', 'This photograph has a rich range of values.', '2008-05-19 07:02:56.000000', NULL, 1),
