(4713272, 678575, 9602, '<td valign="top">think about ironing your backdrop.</td>', 'think about ironing your backdrop.', '2008-05-20 16:37:59.000000', NULL, 1),
(4713273, 678645, 9602, '<td valign="top">I know it is a backdrop, but it looks really fake.</td>', 'I know it is a backdrop, but it looks really fake.', '2008-05-20 16:39:28.000000', NULL, 1),
