(4713278, 677597, 9602, '<td valign="top">Nice twist on the challenge.</td>', 'Nice twist on the challenge.', '2008-05-20 16:42:05.000000', NULL, 1),
(4713279, 677735, 9602, '<td valign="top">Great colors.</td>', 'Great colors.', '2008-05-20 16:42:16.000000', NULL, 1),
(4713291, 677597, 86799, '<td valign="top">Very clever.  Lighting is a little flat, could use just a bit of punch to wake it up.  Otherwise, very cool idea.  Two dead men.</td>', 'Very clever.  Lighting is a little flat, could use just a bit of punch to wake it up.  Otherwise, very cool idea.  Two dead men.', '2008-05-20 16:58:21.000000', NULL, 1),
(4713520, 678520, 93768, '<td valign="top">You got my vote! Beautiful colors &amp; strong contrast.</td>', 'You got my vote! Beautiful colors & strong contrast.', '2008-05-20 21:15:03.000000', NULL, 1),
(4713521, 677156, 93768, '<td valign="top">I like it a lot!</td>', 'I like it a lot!', '2008-05-20 21:15:43.000000', NULL, 1),
(4713537, 678485, 83313, '<td valign="top">Nicely integrates some known challenge-topping elements with the bicycle silhouette. This ought to do well.</td>', 'Nicely integrates some known challenge-topping elements with the bicycle silhouette. This ought to do well.', '2008-05-20 21:39:45.000000', NULL, 1),
(4713540, 678276, 83313, '<td valign="top">Not sure I like the comp and the way the phone lines cut across the frame, but the silhouette is nice and the colors bold and pleasing.</td>', 'Not sure I like the comp and the way the phone lines cut across the frame, but the silhouette is nice and the colors bold and pleasing.', '2008-05-20 21:41:16.000000', NULL, 1),
(4713549, 678524, 83313, '<td valign="top">Bicycle gangs! Riding around like they own the road, beating up teenagers with their frame pumps! Something MUST be done about this modern urban problem. You can usually pick them off at rest stops though. You can use bananas as bait, and once they are off the bike, they can''t move very fast.</td>', 'Bicycle gangs! Riding around like they own the road, beating up teenagers with their frame pumps! Something MUST be done about this modern urban problem. You can usually pick them off at rest stops though. You can use bananas as bait, and once they are off the bike, they can''t move very fast.', '2008-05-20 21:45:29.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4713552, 678115, 83313, '<td valign="top">A bit on the soft side and low in contrast, I''m afraid.<br/> <br/> <br/>I also think there may be a bit of JPEG compression going on here that is robbing you of some detail. Your file size is 90k when you could have used up to 150k.Check the JPEG compression settings in your image editor and always try to save as close to the limit for a challenge as you can get it without going over.</td>', 'A bit on the soft side and low in contrast, I''m afraid.  I also think there may be a bit of JPEG compression going on here that is robbing you of some detail. Your file size is 90k when you could have used up to 150k.Check the JPEG compression settings in your image editor and always try to save as close to the limit for a challenge as you can get it without going over.', '2008-05-20 21:48:44.000000', NULL, 1),
(4713557, 678118, 83313, '<td valign="top">Neat looking sculpture. Haven''t seen many statues that looked like they were having this much fun.</td>', 'Neat looking sculpture. Haven''t seen many statues that looked like they were having this much fun.', '2008-05-20 21:50:23.000000', NULL, 1),
(4713567, 678577, 83313, '<td valign="top">The scene conveys the title perfectly. A fave for this one. I''d love to have a large size version of this to use as a desktop background. <br/> <br/>If it was not outside the challenge rules, I would suggest cloning out the biker in orange. That person tends to draw the eye to the wrong place in the scene.</td>', 'The scene conveys the title perfectly. A fave for this one. I''d love to have a large size version of this to use as a desktop background.  If it was not outside the challenge rules, I would suggest cloning out the biker in orange. That person tends to draw the eye to the wrong place in the scene.', '2008-05-20 21:55:02.000000', NULL, 1),
(4713572, 678645, 83313, '<td valign="top">The flash hurt this some, but it''s a good effort.</td>', 'The flash hurt this some, but it''s a good effort.', '2008-05-20 21:57:32.000000', NULL, 1),
(4713578, 677516, 83313, '<td valign="top">I want to like this one, but I''m finding the whole thing too centered with the crowd in the background drawing my eye from the main subject.</td>', 'I want to like this one, but I''m finding the whole thing too centered with the crowd in the background drawing my eye from the main subject.', '2008-05-20 21:59:54.000000', NULL, 1),
(4713581, 678393, 83313, '<td valign="top">Not bad, but you should make sure to use as much as you can of the available size of 640 pixels and 150k.</td>', 'Not bad, but you should make sure to use as much as you can of the available size of 640 pixels and 150k.', '2008-05-20 22:01:20.000000', NULL, 1),
(4713586, 678638, 83313, '<td valign="top">Lots of visual interest here. The brightly lit wall does pull my eye away from the rider a bit. I''ll be surprised if this isn''t close to the top of the <strike>heap</strike> peloton in this challenge</td>', 'Lots of visual interest here. The brightly lit wall does pull my eye away from the rider a bit. I''ll be surprised if this isn''t close to the top of the heap peloton in this challenge', '2008-05-20 22:03:31.000000', NULL, 1),
(4713594, 677799, 83313, '<td valign="top">Now I''m going to have to go look up what an ausery is...<br/> <br/>ok, you misspelled it, but even spelled right it was a new word for me:<br/> <br/> <br/>os·su·ary Listen to the pronunciation of ossuary<br/>Pronunciation:<br/>    \&amp;#712;ä-sh&amp;#601;-&amp;#716;wer-&amp;#275;, -sy&amp;#601;-, -s&amp;#601;-\ <br/>Function:<br/>    noun <br/>Inflected Form(s):<br/>    plural os·su·ar·ies<br/> <br/>: a depository for the bones of the dead</td>', 'Now I''m going to have to go look up what an ausery is... ok, you misspelled it, but even spelled right it was a new word for me:  os·su·ary Listen to the pronunciation of ossuaryPronunciation:    \&#712;ä-sh&#601;-&#716;wer-&#275;, -sy&#601;-, -s&#601;-\ Function:    noun Inflected Form(s):    plural os·su·ar·ies : a depository for the bones of the dead', '2008-05-20 22:08:04.000000', NULL, 1),
(4713596, 678153, 83313, '<td valign="top">Just needs some air in the tires and some lube on the chain. Oh, wait. strike that suggestion.</td>', 'Just needs some air in the tires and some lube on the chain. Oh, wait. strike that suggestion.', '2008-05-20 22:09:31.000000', NULL, 1),
(4713600, 677346, 83313, '<td valign="top">Very high key. Almost looks like an illustration.</td>', 'Very high key. Almost looks like an illustration.', '2008-05-20 22:10:57.000000', NULL, 1),
(4713613, 678399, 83313, '<td valign="top">Hmmm. The 3rd entry I''ve seen of this same set of bikes. Methinks some people are shooting for challenges as a group. (Nothing wrong with that, as long as you skip voting on your friend''s entries) You took a different perspective from the others, and that''s good. The colors are nice, and I like the perspective view, but the image itself is a little soft and the tiled floor kinda'' doesn''t work, I''m afraid.</td>', 'Hmmm. The 3rd entry I''ve seen of this same set of bikes. Methinks some people are shooting for challenges as a group. (Nothing wrong with that, as long as you skip voting on your friend''s entries) You took a different perspective from the others, and that''s good. The colors are nice, and I like the perspective view, but the image itself is a little soft and the tiled floor kinda'' doesn''t work, I''m afraid.', '2008-05-20 22:17:16.000000', NULL, 1),
(4713615, 677624, 83313, '<td valign="top">Kind of a neat perspective, but it''s just a little on the plain side for me. Maybe if it has a little more DOF it would work better for me.</td>', 'Kind of a neat perspective, but it''s just a little on the plain side for me. Maybe if it has a little more DOF it would work better for me.', '2008-05-20 22:18:37.000000', NULL, 1),
(4713617, 677219, 83313, '<td valign="top">The harsh midday lighting and strong shadows are a problem here, I''m afraid. It seems almost as if there are two photos here. The bike on the right and the stone construct on the left.</td>', 'The harsh midday lighting and strong shadows are a problem here, I''m afraid. It seems almost as if there are two photos here. The bike on the right and the stone construct on the left.', '2008-05-20 22:20:41.000000', NULL, 1),
(4713628, 678519, 83313, '<td valign="top">A really good effort to put together the winning combo of a wideangle landscape and swoopy clouds, but with a bicycle instead of a building. I like the view, though the details seem to lack some visual punch.</td>', 'A really good effort to put together the winning combo of a wideangle landscape and swoopy clouds, but with a bicycle instead of a building. I like the view, though the details seem to lack some visual punch.', '2008-05-20 22:25:26.000000', NULL, 1),
(4713631, 677148, 83313, '<td valign="top">I like this, though I think the focus should have been on the second bike in the lineup, as that is where my eye is naturally drawn by the composition.</td>', 'I like this, though I think the focus should have been on the second bike in the lineup, as that is where my eye is naturally drawn by the composition.', '2008-05-20 22:26:50.000000', NULL, 1),
(4713636, 677171, 83313, '<td valign="top">I can swear I just voted on another entry of this same line of bikes... Good comp, though the bright curb is drawing my eye away from the bikes a little.</td>', 'I can swear I just voted on another entry of this same line of bikes... Good comp, though the bright curb is drawing my eye away from the bikes a little.', '2008-05-20 22:29:17.000000', NULL, 1),
(4713639, 678398, 83313, '<td valign="top">He wears a hardhat for safety at work, but no helmet on the bike. *sigh*</td>', 'He wears a hardhat for safety at work, but no helmet on the bike. *sigh*', '2008-05-20 22:30:10.000000', NULL, 1),
(4713641, 678403, 83313, '<td valign="top">A place with no shortage of bicycles. Nice scene with lots of detail to explore.</td>', 'A place with no shortage of bicycles. Nice scene with lots of detail to explore.', '2008-05-20 22:31:18.000000', NULL, 1),
(4713642, 677234, 83313, '<td valign="top">A nice perspective. Good comp, with sharp detail and good contrast.</td>', 'A nice perspective. Good comp, with sharp detail and good contrast.', '2008-05-20 22:32:13.000000', NULL, 1),
(4713644, 677038, 83313, '<td valign="top">I''m not a big fan of sepia tone myself, but it does seem to enhance this one. the knobbies really stand out.</td>', 'I''m not a big fan of sepia tone myself, but it does seem to enhance this one. the knobbies really stand out.', '2008-05-20 22:33:46.000000', NULL, 1),
(4713648, 677597, 83313, '<td valign="top">I suspect this has gotten DNMC''d to death because it is a subtle detail, but I do recognize the bicycle brand playing cards. Nice out of the box thinking on this. Perhaps a bit of a shoehorn. Maybe. I won''t ding it for that, however. The scene appears a bit dark, but otherwise, I like it.</td>', 'I suspect this has gotten DNMC''d to death because it is a subtle detail, but I do recognize the bicycle brand playing cards. Nice out of the box thinking on this. Perhaps a bit of a shoehorn. Maybe. I won''t ding it for that, however. The scene appears a bit dark, but otherwise, I like it.', '2008-05-20 22:37:35.000000', NULL, 1),
(4713650, 677825, 83313, '<td valign="top">Nice colors and contrast on this. The white bike stands out well against the dark ivy and wall.</td>', 'Nice colors and contrast on this. The white bike stands out well against the dark ivy and wall.', '2008-05-20 22:38:57.000000', NULL, 1),
(4713652, 678514, 83313, '<td valign="top">Ok, I''m dizzy. Makes a nice pattern, and I like the blue background.</td>', 'Ok, I''m dizzy. Makes a nice pattern, and I like the blue background.', '2008-05-20 22:39:59.000000', NULL, 1),
(4713653, 678194, 83313, '<td valign="top">Hard to take a photo and hold the bars at the same time. I''d have given you an extra point or two if you''d had the right hand visible.</td>', 'Hard to take a photo and hold the bars at the same time. I''d have given you an extra point or two if you''d had the right hand visible.', '2008-05-20 22:41:45.000000', NULL, 1),
(4713670, 677776, 77457, '<td valign="top">Great focus on the subject!</td>', 'Great focus on the subject!', '2008-05-20 22:56:15.000000', NULL, 1),
(4713685, 678520, 89515, '<td valign="top">Nice colors! Nice composition as well!</td>', 'Nice colors! Nice composition as well!', '2008-05-20 23:08:54.000000', NULL, 1),
(4713710, 678202, 83313, '<td valign="top">Nice rusty crusty detail.</td>', 'Nice rusty crusty detail.', '2008-05-20 23:25:57.000000', NULL, 1),
(4713712, 678458, 83313, '<td valign="top">Other than the shallow DOF that is inherent in a shot such as this, I really like this one.</td>', 'Other than the shallow DOF that is inherent in a shot such as this, I really like this one.', '2008-05-20 23:27:12.000000', NULL, 1),
(4713729, 678353, 9462, '<td valign="top">It is a modern utopia. <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=670651" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670651.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670651.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670651.jpg"/></a></td>', 'It is a modern utopia. ', '2008-05-20 23:36:58.000000', NULL, 1),
(4713732, 677428, 9462, '<td valign="top">A lovely contrasting duet<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=670650" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670650.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670650.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670650.jpg"/></a></td>', 'A lovely contrasting duet', '2008-05-20 23:37:57.000000', NULL, 1),
(4713741, 678431, 83313, '<td valign="top">DOF seems a little too narrow, and my eye is being drawn away from the bike and over to the railing on the left side. Kind of would like to see it in focus as far back as the saddle.</td>', 'DOF seems a little too narrow, and my eye is being drawn away from the bike and over to the railing on the left side. Kind of would like to see it in focus as far back as the saddle.', '2008-05-20 23:42:32.000000', NULL, 1),
(4713799, 677156, 9462, '<td valign="top">I love the illustration on this one. Riding a bike isn''t always in a straight line or to get from point A to point B, it''s the curves of the journey that make it worthwhile.<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=670652" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670652.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670652.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670652.jpg"/></a></td>', 'I love the illustration on this one. Riding a bike isn''t always in a straight line or to get from point A to point B, it''s the curves of the journey that make it worthwhile.', '2008-05-21 00:23:28.000000', NULL, 1),
(4713833, 677735, 64670, '<td valign="top">Love it - would love to see it larger.</td>', 'Love it - would love to see it larger.', '2008-05-21 00:37:38.000000', NULL, 1),
(4713841, 677867, 64670, '<td valign="top">Lovely subject, the camera shake is excessive.</td>', 'Lovely subject, the camera shake is excessive.', '2008-05-21 00:42:21.000000', NULL, 1),
(4713844, 677831, 64670, '<td valign="top">LOVE IT!  (I''d have ditched the frame - GRIN!)</td>', 'LOVE IT!  (I''d have ditched the frame - GRIN!)', '2008-05-21 00:44:09.000000', NULL, 1),
(4713887, 677776, 77524, '<td valign="top">This looks very much like a road in France I biked. Thanks for the memory.</td>', 'This looks very much like a road in France I biked. Thanks for the memory.', '2008-05-21 01:06:02.000000', NULL, 0),
(4713941, 677735, 49773, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2008-05-21 01:47:44.000000', NULL, 0),
